{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "india5/schemas/status.schema.json",
  "title": "INDIA5 STATUS.yaml",
  "description": "Schema voor de voortgangsstatus van een taak. TASK.yaml is immutable na uitgifte; alle voortgang leeft hier.",
  "type": "object",
  "required": ["task_id", "state", "history"],
  "properties": {
    "task_id": {"type": "string"},
    "state": {
      "type": "string",
      "enum": ["QUEUED", "ACTIVE", "COMPLETED", "FAILED"]
    },
    "claimed_at": {"type": ["string", "null"], "format": "date-time"},
    "claimed_by": {"type": ["string", "null"]},
    "started_at": {"type": ["string", "null"], "format": "date-time"},
    "completed_at": {"type": ["string", "null"], "format": "date-time"},
    "git_commit_at_claim": {
      "type": ["string", "null"],
      "description": "HEAD-commit op het moment van claimen (vóór de claim-commit zelf)."
    },
    "git_commit_at_complete": {
      "type": ["string", "null"],
      "description": "Kan NIET zelfreferentieel in dit bestand staan (de commit die dit bestand bevat, bestaat nog niet op schrijfmoment). Blijft null tot een latere, aparte git-log-opzoeking dit invult, of wordt uitsluitend gerapporteerd in de CCI_RESULT PR-comment na de daadwerkelijke push."
    },
    "completion_marker_found": {
      "type": ["boolean", "null"],
      "description": "True zodra complete_task.py heeft geverifieerd dat RESULT.md de exacte completion_marker uit TASK.yaml bevat."
    },
    "failure_reason": {"type": ["string", "null"]},
    "pre_existing_dirty_paths": {
      "type": "array",
      "items": {"type": "string"},
      "description": "Door claim_task.py vastgelegde snapshot van paden die al gewijzigd/ongetrackt waren VOORDAT deze taak geclaimd werd (bv. ander vastgehouden werk zoals een CCI_HOLD). check_forbidden_writes.py rekent deze paden niet toe aan deze taak."
    },
    "hold": {
      "type": "object",
      "description": "Instructieprecedentie punt 2: een expliciete HOLD/ABORT-status in de taakbestanden zelf staat BOVEN Mark-besluitenregister, PR-comments, chattekst en lokale hooks (maar ONDER de canonieke TASK.yaml/TASK.md zelf). Zolang hold.active=true, mag CCI de TASK.md-instructies niet uitvoeren, alleen lezen/wachten/rapporteren.",
      "required": ["active", "reason", "set_at", "set_by"],
      "properties": {
        "active": {"type": "boolean"},
        "reason": {"type": ["string", "null"]},
        "set_at": {"type": ["string", "null"], "format": "date-time"},
        "set_by": {"type": ["string", "null"]}
      }
    },
    "result_comment_posted": {
      "type": "boolean",
      "description": "True zodra de CCI_RESULT(_ENVELOPE)-comment daadwerkelijk op de PR is geplaatst. Voorkomt dat een hervattende sessie na een completion-move zonder comment (crashtoestand d) de comment dubbel of nooit post."
    },
    "history": {
      "type": "array",
      "description": "Append-only logboek van state-overgangen, nooit eerdere regels overschrijven.",
      "items": {
        "type": "object",
        "required": ["at", "event"],
        "properties": {
          "at": {"type": "string", "format": "date-time"},
          "event": {"type": "string"},
          "detail": {"type": "string"}
        }
      }
    }
  },
  "additionalProperties": false
}
